int count=0;

void countSort(int a[],int n,int exp) {
    int output[n],bucket[10],i;

    for(i=0;i<10;i++)
        bucket[i]=0;
    for(i=0;i<n;i++) {
        count++;
        bucket[(a[i]/exp)%10]++;
    }
    for(i=1;i<10;i++)
        bucket[i]=bucket[i]+bucket[i-1];
    for(i=n-1;i>=0;i--) {
        count++;
        output[--bucket[(a[i]/exp)%10]]=a[i];
    }
    for(i=0;i<n;i++)
        a[i]=output[i];
}

