int count=0;

int partition(int a[],int low,int high) {
    int pivot=a[high];
    int i=low-1,j,temp;

    for(j=low;j<high;j++) {
        count++;
        if(a[j]<=pivot) {
            i++;
            temp=a[i];
            a[i]=a[j];
            a[j]=temp;
        }
    }
    temp=a[i+1];
    a[i+1]=a[high];
    a[high]=temp;
    return i+1;
}

void quickSort(int a[],int low,int high) {
    if(low<high) {
        int p=partition(a,low,high);
        quickSort(a,low,p-1);
        quickSort(a,p+1,high);
    }
}

