void heapify(int i) {
    int smallest=i,l=2*i+1,r=2*i+2;
    if(l<qsize) {
        comp++;
        if(f[Q[l]]<f[Q[smallest]])
            smallest=l;
    }
    if(r<qsize) {
        comp++;
        if(f[Q[r]]<f[Q[smallest]])
            smallest=r;
    }
    if(smallest!=i) {
        int t=Q[i];
        Q[i]=Q[smallest];
        Q[smallest]=t;
        heapify(smallest);
    }
}

int extractMin() {
    int min=Q[0];
    Q[0]=Q[qsize-1];
    qsize--;
    heapify(0);
    return min;
}

void insert(int z) {
    int i=qsize;
    Q[qsize++]=z;
    while(i>0) {
        int p=(i-1)/2;
        comp++;
        if(f[Q[i]]>=f[Q[p]])
            break;
        int t=Q[i];
        Q[i]=Q[p];
        Q[p]=t;
        i=p;
    }
}

void printCodes(int z,int depth) {
    int i;
