int main() {
    int n,i,j,k,S,full,count=0;
    printf("Enter the number of cities:");
    scanf("%d",&n);
    printf("Enter the %dx%d cost matrix:\n",n,n);
    for(i=0;i<n;i++)
        for(j=0;j<n;j++)
            scanf("%d",&cost[i][j]);

    clock_t start=clock();
    // S is a bitmask of cities; bit 0 (city 1) is never in S
    full=(1<<n)-1;
    for(i=0;i<n;i++)
        g[0][i]=cost[i][0];
    for(S=1;S<=full;S++) {
        if(S&1)
            continue;
        for(i=0;i<n;i++) {
            if(S&(1<<i))
                continue;
            g[S][i]=999999999;
            for(k=1;k<n;k++) {
                if(S&(1<<k)) {
                    count++;
                    int c=cost[i][k]+g[S^(1<<k)][k];
                    if(c<g[S][i]) {
                        g[S][i]=c;
                        nxt[S][i]=k;
                    }
                }
            }
        }
    }
    S=full^1;
    clock_t end=clock();
    double time_taken=(double)(end-start)/CLOCKS_PER_SEC;

    printf("\nMinimum cost of tour:%d",g[S][0]);
    printf("\nOptimal tour:1");
    i=0;
    while(S!=0) {
        k=nxt[S][i];
        printf(" -> %d",k+1);
        S=S^(1<<k);
        i=k;
    }
    printf(" -> 1");
    printf("\nNumber of comparisons:%d",count);
    printf("\nTime taken:%f seconds",time_taken);
    printf("\nTime complexity: O(n^2 * 2^n)");
    printf("\nSpace complexity: O(n * 2^n)");
    printf("\n");
    return 0;
}

