        for(j=1;j<=n;j++)
            scanf("%d",&c[i][j]);

    int order[MAX],first[MAX];

    clock_t start=clock();
    new_node(-1,0);
    while(1) {
        E=-1;
        for(k=0;k<total;k++) {
            if(live[k]) {
                count++;
                if(E==-1 || lb[k]<lb[E])
                    E=k;
            }
        }
        if(E==-1)
            break;
        live[E]=0;
        if(level[E]==n) {
            ans=E;
            break;
        }
        order[expanded]=E;
        first[expanded]=total;
        expanded++;
        for(j=1;j<=n;j++)
            if(!(used[E]&(1<<j)))
                new_node(E,j);
    }
    clock_t end=clock();
    double time_taken=(double)(end-start)/CLOCKS_PER_SEC;

    printf("\nNodes expanded (least lb first):");
    for(i=0;i<expanded;i++) {
        E=order[i];
