            if(d[i]==INF)
                printf("\n%d\tunreachable",i);
            else {
                printf("\n%d\t%d\t\t",i,d[i]);
                path(i);
            }
        }
    }
    printf("\nNumber of comparisons:%d",count);
    printf("\nTime taken:%f seconds",time_taken);
    printf("\nTime complexity: O(VE)");
