#include<stdio.h>
#include<time.h>
#define INF 99999

int n,count=0;
int w[50][50],key[50],p[50],Q[50];

int extract_min() {
    int v,u=0;
    for(v=1;v<=n;v++) {
        count++;
        if(Q[v]==1 && (u==0 || key[v]<key[u]))
            u=v;
    }
    Q[u]=0;
    return u;
}

int main() {
    int i,u,v,r,q_size,step=0,cost=0;
    printf("Enter the number of vertices:");
    scanf("%d",&n);
    printf("Enter the %dx%d weight matrix (0 for no edge):\n",n,n);
    for(u=1;u<=n;u++)
        for(v=1;v<=n;v++)
            scanf("%d",&w[u][v]);
    printf("Enter the root vertex:");
    scanf("%d",&r);

    int order[n+1];

    clock_t start=clock();
    for(u=1;u<=n;u++) {
        key[u]=INF;
        p[u]=0;
    }
    key[r]=0;
    for(u=1;u<=n;u++)
        Q[u]=1;
    q_size=n;
    while(q_size!=0) {
        u=extract_min();
        q_size--;
        if(key[u]==INF)
            break;
        step++;
        order[step]=u;
        for(v=1;v<=n;v++)
            if(w[u][v]!=0) {
                count++;
                if(Q[v]==1 && w[u][v]<key[v]) {
                    p[v]=u;
                    key[v]=w[u][v];
                }
            }
    }
    clock_t end=clock();
    double time_taken=(double)(end-start)/CLOCKS_PER_SEC;

    if(step<n)
        printf("\nGraph is disconnected, no spanning tree exists");
    else {
        printf("\nEdges in the minimum spanning tree (in the order added):");
        printf("\nEdge\t\tWeight");
        for(i=2;i<=n;i++) {
            v=order[i];
            printf("\n%d - %d\t\t%d",p[v],v,key[v]);
            cost+=key[v];
        }
        printf("\nMinimum cost of spanning tree:%d",cost);
    }
    printf("\nNumber of comparisons:%d",count);
    printf("\nTime taken:%f seconds",time_taken);
    printf("\nTime complexity: O(V^2) with adjacency matrix, O(E log V) with adjacency list and binary heap");
    printf("\nSpace complexity: O(V^2) with adjacency matrix, O(V+E) with adjacency list");
    printf("\n");
    return 0;
}

#include<stdio.h>
#include<time.h>

int parent[50],rnk[50];

void make_set(int x) {
    parent[x]=x;
    rnk[x]=0;
}

int find_set(int x) {
    if(x!=parent[x])
        parent[x]=find_set(parent[x]);
    return parent[x];
}

void union_set(int x,int y) {
    x=find_set(x);
    y=find_set(y);
    if(rnk[x]>rnk[y])
        parent[y]=x;
    else {
        parent[x]=y;
        if(rnk[x]==rnk[y])
            rnk[y]++;
    }
}

int main() {
    int n,e,i,j,k=0,cost=0,count=0,tu,tv,tw;
    printf("Enter the number of vertices:");
    scanf("%d",&n);
    printf("Enter the number of edges:");
    scanf("%d",&e);
    int u[e],v[e],w[e],au[n],av[n],aw[n];
    printf("Enter the edges (vertex vertex weight):\n");
    for(i=0;i<e;i++)
        scanf("%d%d%d",&u[i],&v[i],&w[i]);

    clock_t start=clock();
    for(i=1;i<=n;i++)
        make_set(i);
    for(i=1;i<e;i++) {
        tu=u[i];
        tv=v[i];
        tw=w[i];
        j=i-1;
        while(j>=0) {
            count++;
            if(w[j]<=tw)
                break;
            u[j+1]=u[j];
            v[j+1]=v[j];
            w[j+1]=w[j];
            j--;
        }
        u[j+1]=tu;
        v[j+1]=tv;
        w[j+1]=tw;
    }
    for(i=0;i<e && k<n-1;i++) {
        count++;
        if(find_set(u[i])!=find_set(v[i])) {
            au[k]=u[i];
            av[k]=v[i];
            aw[k]=w[i];
            k++;
            union_set(u[i],v[i]);
        }
    }
    clock_t end=clock();
    double time_taken=(double)(end-start)/CLOCKS_PER_SEC;

    if(k<n-1)
        printf("\nGraph is disconnected, no spanning tree exists");
    else {
        printf("\nEdges in the minimum spanning tree (in the order added):");
        printf("\nEdge\t\tWeight");
        for(i=0;i<k;i++) {
            printf("\n%d - %d\t\t%d",au[i],av[i],aw[i]);
            cost+=aw[i];
        }
        printf("\nMinimum cost of spanning tree:%d",cost);
    }
    printf("\nNumber of comparisons:%d",count);
    printf("\nTime taken:%f seconds",time_taken);
    printf("\nTime complexity: O(E log E) with merge sort, O(E^2) with the insertion sort used here");
    printf("\nSpace complexity: O(V+E)");
    printf("\n");
    return 0;
}
